package com.unicare.dispensary.medication;
import jakarta.validation.Valid;import java.security.Principal;import java.util.List;import org.springframework.web.bind.annotation.*;import org.springframework.http.HttpStatus;
@RestController @RequestMapping("/api/staff/medications") public class StaffPrescriptionController{private final PrescriptionService service;public StaffPrescriptionController(PrescriptionService s){service=s;}@GetMapping public List<PrescriptionResponse> list(){return service.all();}@PostMapping @org.springframework.web.bind.annotation.ResponseStatus(HttpStatus.CREATED) public PrescriptionResponse issue(@Valid @RequestBody PrescriptionRequest r,Principal p){return service.issue(r,p.getName());}@PatchMapping("/{id}/status") public PrescriptionResponse status(@PathVariable Long id,@Valid @RequestBody StatusRequest r){return service.status(id,r.status());}public record StatusRequest(@jakarta.validation.constraints.NotNull PrescriptionStatus status){}}
